const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const RANCH_ROLE_ID='1557403792088104980';
const BUILD_LABEL='Ranch Panel · nouvelle interface';
const cash=n=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' $';
const orderDetails=o=>{const items=o.data?.items||o.data?.lines||o.data?.products;if(!Array.isArray(items))return o.products||'';return items.map(i=>{const name=String(i.name||i.product||i.article||'Article'),qty=Number(i.quantity??i.qty??1),article=articles.find(a=>a.name?.trim().toLowerCase()===name.trim().toLowerCase()),factor=Number(article?.data?.unitsPerOrder||1);return name+' : '+qty+' Discord = '+(qty*factor)+' unités'}).join(' ; ')};
function downloadPayrollCsv(rows){const csvCell=v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s=String.fromCharCode(39)+s;return '"'+s.replaceAll('"','""')+'"'};const headers=['Date','Employé','Grade','Début période','Fin période','Récoltes','Livraisons','Commandes','Prime direction','Avance','Prime exceptionnelle','Ancienneté','Total','Payé par'];const values=rows.map(x=>[x.payroll_date,x.employee,x.grade,x.data?.period_from||'',x.data?.period_to||'',x.harvest_amount,x.delivery_amount,x.order_amount,x.management_bonus,x.weekly_advance,x.exceptional_bonus,x.senior_bonus,x.total_amount,x.paid_by]);const csv=[headers,...values].map(row=>row.map(csvCell).join(';')).join('\r\n');const blob=new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ranch-historique-paies.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadOrdersCsv(rows){const csvCell=v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s=String.fromCharCode(39)+s;return String.fromCharCode(34)+s.replaceAll(String.fromCharCode(34),String.fromCharCode(34,34))+String.fromCharCode(34)};const data=[['Date','Numéro','Entreprise','Téléphone','Produits','Montant','Statut'],...rows.map(o=>[o.order_date||o.created_at,o.order_number,o.company,o.phone,orderDetails(o),o.total_amount,o.status])].map(row=>row.map(csvCell).join(';')).join(String.fromCharCode(13,10));const blob=new Blob([String.fromCharCode(65279),data],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ranch-commandes.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let session,member,tab='home',articles=[],harvests=[],deliveries=[],payroll=[],employees=[],settings=[],orders=[];
let ordersChannel=null,ordersRefreshBusy=false,ordersRefreshTimer=null,ordersPageState=0;
async function refreshOrdersLive(){
  if(!db||!session||!member||ordersRefreshBusy||tab!=='orders'||document.hidden)return;
  ordersRefreshBusy=true;
  const activeUserId=session.user.id;
  try{
    const data=await fetchAllRows('ranch_orders');
    if(!session||session.user.id!==activeUserId||!member||tab!=='orders')return;
    const orderSnapshot=list=>JSON.stringify(list.map(x=>[x.id,x.status,x.updated_at,x.order_number,x.order_date,x.company,x.phone,x.products,x.total_amount,x.employee_in_charge,x.data]));
    const before=orderSnapshot(orders);
    orders=data;
    const after=orderSnapshot(orders);
    if(before!==after&&tab==='orders'){const searchBox=document.querySelector('#order-search'),statusBox=document.querySelector('#order-status');const search=searchBox?.value||'',status=statusBox?.value||'';const focused=document.activeElement===searchBox?'search':document.activeElement===statusBox?'status':null;const caret=focused==='search'?searchBox.selectionStart:null;const selectionEnd=focused==='search'?searchBox.selectionEnd:null;view();const nextSearch=document.querySelector('#order-search'),nextStatus=document.querySelector('#order-status');if(nextSearch&&nextStatus){nextSearch.value=search;nextStatus.value=status;nextSearch.dispatchEvent(new Event('orders-refresh'));if(focused==='search'){nextSearch.focus();if(caret!==null)nextSearch.setSelectionRange(caret,selectionEnd??caret)}else if(focused==='status')nextStatus.focus()}}
  }catch(e){console.warn('Ranch orders refresh',e.message)}
  finally{ordersRefreshBusy=false}
}
function startOrdersLive(){
  if(ordersChannel||!db)return;
  ordersChannel=db.channel('ranch-orders-live').on('postgres_changes',{event:'*',schema:'public',table:'ranch_orders'},()=>{refreshOrdersLive()}).subscribe();
  ordersRefreshTimer=setInterval(refreshOrdersLive,15000);
}

async function stopOrdersLive(){if(ordersRefreshTimer!==null){clearInterval(ordersRefreshTimer);ordersRefreshTimer=null}if(ordersChannel&&db){await db.removeChannel(ordersChannel);ordersChannel=null}ordersRefreshBusy=false}
const admin=()=>['admin','manager','patron','co-patron','contre maître','contre-maître','contre_maitre'].includes(String(member?.role||'').trim().toLocaleLowerCase('fr'));
const mine=(rows,col)=>admin()?rows:rows.filter(x=>x.data?.user_id===session.user.id||x.user_id===session.user.id||x[col]===who());
const who=()=>{const m=session?.user?.user_metadata||{};return m.global_name||m.globalName||m.discord_global_name||m.full_name||m.name||employees.find(x=>x.user_id===session?.user?.id)?.name||session?.user?.email||'Fermier'};
const tbl=(heads,rows)=>'<div class="scroll"><table><thead><tr>'+heads.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
function message(s,bad=false){const el=document.querySelector('#notice');if(el){el.textContent=s;el.className=bad?'bad':'good'}}
async function fetchAllRows(name){const all=[],pageSize=500,limit=50000,keyColumn=name==='ranch_settings'?'key':'id';let lastKey=null;while(true){let query=db.from(name).select('*').order(keyColumn,{ascending:true}).limit(Math.min(pageSize,limit-all.length+1));if(lastKey!==null)query=query.gt(keyColumn,lastKey);const {data,error}=await query;if(error)throw error;const page=data||[];if(!page.length)return all;if(all.length+page.length>limit)throw Error('Limite de chargement atteinte pour '+name+' ('+limit+' lignes)');const nextKey=page[page.length-1][keyColumn];if(nextKey===null||nextKey===undefined||nextKey===lastKey)throw Error('Pagination invalide pour '+name);if(page.some((row,i)=>row[keyColumn]===null||row[keyColumn]===undefined||(i>0&&String(row[keyColumn])===String(page[i-1][keyColumn]))))throw Error('Clé de pagination dupliquée ou absente pour '+name);all.push(...page);lastKey=nextKey;if(page.length<pageSize)return all}}
let loadGeneration=0;
async function load(){const generation=++loadGeneration,userId=session?.user?.id;const names=['ranch_articles','ranch_harvests','ranch_deliveries','ranch_payroll_history','ranch_employees','ranch_settings','ranch_orders'];const result=await Promise.all(names.map(fetchAllRows));if(generation!==loadGeneration||session?.user?.id!==userId)return false;[articles,harvests,deliveries,payroll,employees,settings,orders]=result;return true}
function login(){app.innerHTML='<div class="ranch-auth"><div class="auth-scenery"><div class="auth-brand"><span>🌾</span><strong>LUCKY JIM’S RANCH</strong></div><div class="auth-hero-copy"><span class="eyebrow">GRAPESEED • SAN ANDREAS</span><h1>Bienvenue<br>à la ferme.</h1><p>Le cœur de votre exploitation : récoltes, commandes, livraisons et équipe.</p></div><div class="auth-scenery-foot">CULTIVÉ AVEC PASSION • DEPUIS GRAPESEED</div></div><div class="auth-form-side"><div class="auth-form-card"><span class="auth-badge">✦ ESPACE DES EMPLOYÉS</span><h2>Heureux de vous revoir.</h2><p>Connectez-vous avec votre compte Discord du Ranch pour retrouver votre espace de travail.</p>'+(!db?'<p class="bad">Connexion Supabase non configurée.</p>':'')+'<button id="discord-login" class="discord-login" type="button">◈ Continuer avec Discord →</button><div class="auth-rule"><span>ACCÈS SÉCURISÉ</span></div><p class="auth-hint">Seuls les membres autorisés du serveur Lucky Jim’s Ranch peuvent accéder au panel.</p><small class="auth-hint">'+BUILD_LABEL+'</small><p id="notice" role="status" aria-live="polite"></p></div></div></div>';const btn=document.querySelector('#discord-login');btn.onclick=async()=>{if(!db)return message('Connexion Supabase non configurée : vérifie les variables GitHub Actions puis redéploie.',true);btn.disabled=true;btn.textContent='Connexion à Discord en cours…';message('Ouverture de Discord…');try{const check=await fetch(url.replace(/\/$/,'')+'/auth/v1/health',{headers:{apikey:key}});if(check.status===401||check.status===403)throw Error('Clé publique refusée par Supabase Ranch (HTTP '+check.status+').');const redirectTo=window.location.origin+import.meta.env.BASE_URL+'?ranch_auth_version=20261014-v8';const {data,error}=await db.auth.signInWithOAuth({provider:'discord',options:{redirectTo,scopes:'identify email guilds.members.read',skipBrowserRedirect:true}});if(error)throw error;if(!data?.url)throw Error('Supabase n’a pas retourné de lien de connexion Discord. Vérifie le fournisseur Discord dans Supabase.');window.location.assign(data.url)}catch(error){message('Connexion Discord impossible : '+(error?.message||'erreur inconnue'),true);btn.disabled=false;btn.textContent='🎮 Réessayer avec Discord'}}}
async function boot(){
  if(!db)return login();
  const params=new URLSearchParams(window.location.search);
  const hash=new URLSearchParams(window.location.hash.slice(1));
  const authError=params.get('error_description')||params.get('error')||hash.get('error_description')||hash.get('error');
  // Laisser supabase-js terminer le callback implicite et stocker la session.
  let callbackError=null;
  let sessionError=null;
  try {
    const result=await db.auth.initialize();
    if(result.error)callbackError=result.error.message;
    const resultSession=await db.auth.getSession();
    session=resultSession.data?.session;
    sessionError=resultSession.error;
  }catch(e){callbackError=e?.message||String(e)}
  if(!session){
    login();
    if(authError)message('Discord / Supabase : '+authError,true);
    else if(callbackError)message('Retour Discord : '+callbackError,true);
    else if(sessionError)message('Session Supabase : '+sessionError.message,true);
    else if(params.has('code')||hash.has('access_token'))message('Code OAuth reçu, mais aucune session créée. Vérifie le stockage navigateur et réessaie.',true);
    return;
  }
  if(window.location.search||window.location.hash)window.history.replaceState({},'',window.location.pathname);
  try{
    if(!session.provider_token)throw Error('Autorisation Discord manquante. Déconnecte-toi puis reconnecte-toi pour autoriser la lecture des rôles.');
    const checkRoles=await db.functions.invoke('ranch-discord-access',{body:{provider_token:session.provider_token}});
    if(checkRoles.error){let detail=checkRoles.error.message;try{const payload=await checkRoles.error.context?.json();detail=payload?.error||detail}catch(_){}throw Error('Vérification des grades Discord : '+detail)}
    const r=await db.from('ranch_memberships').select('*').eq('user_id',session.user.id).eq('active',true).maybeSingle();
    if(r.error)throw Error('Vérification des droits Ranch : '+r.error.message);
    if(!r.data)throw Error('Grades vérifiés mais droits Ranch non enregistrés. Contacte la direction.');
    member=r.data;
    await load();
    draw();
    startOrdersLive();
  }catch(e){
    app.innerHTML='<div class="ranch-auth"><div class="auth-scenery"><div class="auth-brand"><span>🌾</span><strong>LUCKY JIM’S RANCH</strong></div><div class="auth-hero-copy"><span class="eyebrow">GRAPESEED • SAN ANDREAS</span><h1>Accès au<br>Ranch.</h1><p>Votre espace de gestion, réservé à l’équipe.</p></div><div class="auth-scenery-foot">LUCKY JIM’S RANCH</div></div><div class="auth-form-side"><div class="auth-form-card"><span class="auth-badge">AUTHENTIFICATION</span><h2>Connexion impossible</h2><p class="bad">'+esc(e.message)+'</p><button id="out" class="discord-login">↪ Se déconnecter et réessayer</button></div></div></div>';
    document.querySelector('#out').onclick=async()=>{await stopOrdersLive();await db.auth.signOut();session=null;member=null;articles=[];harvests=[];deliveries=[];payroll=[];employees=[];settings=[];orders=[];login()};
  }
}
const menuItems=()=>[['home','⌂','Vue d’ensemble'],['harvest','🌿','Récoltes'],['orders','▣','Commandes'],['delivery','↗','Livraisons'],...(admin()?[['settings','⚙','Paramètres']]:[])];
const themeChoices=[['light','☀️ Jour clair'],['dark','🌙 Nuit profonde'],['forest','🌲 Forêt'],['sunset','🌅 Coucher de soleil'],['lavender','💜 Lavande'],['sand','🏜️ Sable']];
