if(tab==='billing'){const delivered=deliveries.filter(x=>x.order_number&&String(x.validated_by||'').trim());const pending=deliveries.filter(x=>x.order_number&&!String(x.validated_by||'').trim());const deliveredNumbers=new Set(delivered.map(d=>String(d.order_number).trim()));const deliveredOrderMap=new Map(orders.map(o=>[String(o.order_number).trim(),o]));const completed=orders.filter(o=>['validé & payé','valide & paye','paid','payé','payee'].includes(String(o.status||'').toLowerCase()));const archives=completed.filter(o=>!deliveredNumbers.has(String(o.order_number).trim()));const rows=delivered.map(d=>{const o=deliveredOrderMap.get(String(d.order_number).trim());return [d.delivery_date||d.created_at?.slice(0,10),d.order_number,o?.company||'—',d.farmer_driver,o?cash(o.total_amount):'Non renseigné',o?.status||'Livré']});el.innerHTML='<div class="section-intro"><div><span class="eyebrow">ARCHIVES COMMERCIALES</span><h2>Registre des facturations</h2><p>Uniquement les livraisons validées avec une commande associée. Aucun devis ni facture à créer.</p></div></div><div class="panel"><h3>Livraisons validées</h3><div class="stats"><div class="stat">🚚 Livraisons rapprochées<strong>'+delivered.length+'</strong></div><div class="stat">📚 Archives non rapprochées<strong>'+archives.length+'</strong></div><div class="stat">💵 Montant des commandes livrées (sans doublons)<strong>'+cash([...deliveredNumbers].reduce((s,n)=>s+Number(deliveredOrderMap.get(n)?.total_amount||0),0))+'</strong></div></div>'+tbl(['Date de livraison','Commande','Entreprise','Livreur','Montant de commande','Statut'],rows.reverse())+'</div>'+(pending.length?'<div class="panel"><h3>Livraisons en attente de validation</h3><p>Ces livraisons ne figurent pas dans le registre des facturations tant qu’un responsable ne les a pas validées.</p>'+tbl(['Date','Commande','Livreur','État'],pending.map(x=>[x.delivery_date,x.order_number,x.farmer_driver,'En attente']).reverse())+'</div>':'')+(archives.length?'<div class="panel"><h3>Archives historiques — sans livraison enregistrée</h3><p>Ces commandes payées sont conservées à part et ne comptent pas comme livraisons effectuées.</p>'+tbl(['Date de commande','Commande','Entreprise','Montant','Statut'],archives.map(o=>[o.order_date,o.order_number,o.company,cash(o.total_amount),o.status]).reverse())+'</div>':'')}
if(tab==='stock'&&admin()){const stockRows=articles.flatMap(a=>(Array.isArray(a.data?.stockMovements)?a.data.stockMovements:[]).map(m=>[m.date||'',a.name,m.author||'—',m.operation==='add'?'Entrée':m.operation==='remove'?'Sortie':'Inventaire',m.quantity,m.before,m.after,m.reason||'—'])).sort((a,b)=>String(b[0]).localeCompare(String(a[0]))).slice(0,200).map(r=>[r[0]?new Date(r[0]).toLocaleString('fr-FR'):'—',...r.slice(1)]);el.innerHTML='<div class="section-intro"><div><span class="eyebrow">GESTION DES RESSOURCES</span><h2>Stocks & recettes</h2><p>Stocks et recettes de transformation repris du Google Sheets original.</p></div></div><div class="panel">'+tbl(['Article','Stock relevé','Maximum','Recette de transformation','Suivi'],articles.map(a=>[a.name,a.data?.stockCurrent??'—',a.data?.stockMax??'—',a.data?.recipe||'Récolte directe',a.data?.stockTracking?'Activé':'Non activé']))+'<h3>Historique des mouvements</h3>'+tbl(['Date','Article','Employé','Opération','Quantité','Avant','Après','Motif'],stockRows)+'<h3>Transformer selon une recette</h3><p>Les ingrédients sont déduits et le produit fabriqué est ajouté au stock en une seule opération.</p><form id="stock-transform"><label>Produit<select name="id">'+articles.filter(a=>String(a.data?.recipe||'').trim()).map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+'</option>').join('')+'</select></label><label>Quantité à fabriquer<input name="quantity" type="number" min="1" max="10000" step="1" required></label><button>Fabriquer</button></form><h3>Mouvement de stock</h3><p>Ajoutez, retirez ou corrigez un stock. Chaque mouvement conserve sa date, son auteur et son motif.</p><form id="stock-edit"><label>Article<select name="id">'+articles.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+'</option>').join('')+'</select></label><label>Opération<select name="operation"><option value="add">Entrée (+)</option><option value="remove">Sortie (−)</option><option value="set">Inventaire (valeur exacte)</option></select></label><label>Quantité<input name="stock" type="number" min="0" step="1" required></label><label>Motif<input name="reason" maxlength="160" required placeholder="Livraison fournisseur, transformation, inventaire…"></label><button>Enregistrer le mouvement</button></form></div>';document.querySelector('#stock-transform').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),id=Number(f.get('id')),quantity=Number(f.get('quantity'));if(!Number.isSafeInteger(id)||!Number.isSafeInteger(quantity)||quantity<1)return message('Quantité invalide.',true);const result=await db.rpc('ranch_transform_stock',{p_article_id:id,p_quantity:quantity});if(result.error)return message(result.error.message,true);await load();draw();message('Transformation enregistrée : '+quantity+' × '+(result.data?.product||'produit')+'.')};document.querySelector('#stock-edit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),a=articles.find(x=>String(x.id)===String(f.get('id'))),amount=Number(f.get('stock')),op=String(f.get('operation')),reason=String(f.get('reason')||'').trim(),before=Number(a?.data?.stockCurrent||0);if(!a||!Number.isSafeInteger(amount)||amount<0||!['add','remove','set'].includes(op)||!reason||!Number.isFinite(before))return message('Mouvement de stock invalide.',true);const stock=op==='set'?amount:before+(op==='add'?amount:-amount);const max=Number(a.data?.stockMax);if(!Number.isSafeInteger(stock)||stock<0)return message('Stock insuffisant ou valeur invalide.',true);if(a.data?.stockMax!==undefined&&a.data?.stockMax!==null&&a.data?.stockMax!==''&&Number.isFinite(max)&&max>0&&stock>max)return message('Stock supérieur au maximum autorisé ('+max+').',true);const result=await db.rpc('ranch_adjust_stock',{p_article_id:a.id,p_operation:op,p_quantity:amount,p_reason:reason});if(result.error)return message(result.error.message,true);const finalStock=result.data?.after??stock;await load();draw();message('Mouvement enregistré : '+before+' → '+finalStock+'.')}} 
