if(tab==='settings'&&admin()){const rulesKey='company_rules';const existing=settings.find(s=>s.key===rulesKey)?.value;const rules=Array.isArray(existing)?existing:[{name:'Ornies',type:'Restaurant',keywords:['orni','orniesburger']},{name:'Taco Farmer',type:'Restaurant',keywords:['tacofarmer']},{name:'Yellowjack',type:'Bar',keywords:['yellowjack']},{name:'Rex Diner',type:'Restaurant',keywords:['rex','rexs','rexdiner']}];const box=document.createElement('div');box.className='panel';box.innerHTML='<h2>🏢 Entreprises et mots-clés Discord</h2><p>Associez les noms reçus depuis Discord à une tuile. Les noms non reconnus vont dans « Autres ».</p><div id="company-rules-list"></div><h3>Créer une entreprise</h3><form id="company-rule-add"><label>Nom de la tuile<input name="name" required></label><label>Type d’entreprise<input name="type" placeholder="Restaurant, bar, commerce…" required></label><label>Mots-clés Discord (séparés par des virgules)<input name="keywords" required></label><button>Créer la tuile</button></form>';document.querySelector('#content').appendChild(box);const listing=box.querySelector('#company-rules-list');const save=async next=>{const result=await db.from('ranch_settings').upsert({key:rulesKey,value:next},{onConflict:'key'});if(result.error)return message(result.error.message,true);await load();draw();message('Entreprises mises à jour')};for(const rule of rules){const form=document.createElement('form');form.style.cssText='border-top:1px solid #8884;padding:12px 0';form.innerHTML='<strong>'+esc(rule.name)+'</strong><label>Type<input name="type" value="'+esc(rule.type||'Autre')+'" required></label><label>Mots-clés Discord<input name="keywords" value="'+esc((rule.keywords||[]).join(', '))+'"></label><button>Enregistrer cette entreprise</button>';form.onsubmit=e=>{e.preventDefault();const data=new FormData(form);save(rules.map(r=>r===rule?{...r,type:String(data.get('type')),keywords:String(data.get('keywords')).split(',').map(s=>s.trim()).filter(Boolean)}:r))};listing.appendChild(form)}box.querySelector('#company-rule-add').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),name=String(data.get('name')).trim();if(rules.some(r=>r.name.toLowerCase()===name.toLowerCase()))return message('Cette entreprise existe déjà',true);save([...rules,{name,type:String(data.get('type')),keywords:String(data.get('keywords')).split(',').map(s=>s.trim()).filter(Boolean)}])}}
