if(tab==='delivery'){const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const delivered=new Set(deliveries.map(x=>String(x.order_number||'').trim()).filter(Boolean));const readyOrders=orders.filter(o=>['prete','pret','ready'].includes(norm(o.status))&&!delivered.has(String(o.order_number||'').trim()));el.innerHTML='<div class="panel"><h2>🚚 Commandes prêtes à livrer</h2><p>Seules les commandes validées comme prêtes apparaissent ici. Choisissez une tuile pour enregistrer la livraison.</p><div id="ready-deliveries" class="stats"></div></div><div class="panel"><h2>Historique des livraisons</h2>'+tbl(['Date','Commande','Livreur','Prime','Validation'],d.slice().reverse().map(x=>[x.delivery_date,x.order_number||'Sans commande',x.farmer_driver,cash(x.bonus_amount),x.validated_by||'En attente']))+'</div>';const root=document.querySelector('#ready-deliveries');if(!readyOrders.length){root.textContent='Aucune commande prête à livrer pour le moment.'}for(const o of readyOrders){const tile=document.createElement('div');tile.className='stat';const title=document.createElement('strong');title.textContent=(o.company||'Entreprise')+' · '+(o.order_number||'#'+o.id);tile.appendChild(title);const info=document.createElement('p');info.textContent=[o.products,o.total_amount!=null?cash(o.total_amount):''].filter(Boolean).join(' · ');tile.appendChild(info);const btn=document.createElement('button');btn.type='button';btn.textContent='🚚 Valider la livraison';btn.onclick=async()=>{btn.disabled=true;const result=await db.rpc('ranch_record_delivery',{p_order_number:o.order_number});if(result.error){btn.disabled=false;message(result.error.message,true);return}await load();draw();message('Livraison enregistrée pour '+o.order_number)};tile.appendChild(btn);root.appendChild(tile)}}
if(tab==='pay'){const paid=new Set(['paid','payee','payé','payée','encaissée','encaissee','encaissé','encaisse','validé & payé','valide & paye','validée & payée','réglé','regle','réglée','reglee']);const income=orders.filter(x=>paid.has(String(x.status||'').trim().toLocaleLowerCase('fr'))).reduce((s,x)=>s+Number(x.total_amount||0),0),expenses=payroll.reduce((s,x)=>s+Number(x.total_amount||0),0);const payrollForm=admin()?'<div class="panel"><h3>Enregistrer une paie</h3><p>Les montants sont saisis par un responsable ; l’avance est déduite du total.</p><form id="payroll-new"><label>Employé<select name="employee">'+employees.filter(e=>e.active!==false).map(e=>'<option value="'+esc(e.name)+'">'+esc(e.name)+'</option>').join('')+'</select></label>'+[['harvest','Récoltes'],['delivery','Livraisons'],['order','Commandes'],['management','Prime direction'],['advance','Avance à déduire'],['exceptional','Prime exceptionnelle'],['senior','Ancienneté']].map(([id,label])=>'<label>'+label+'<input name="'+id+'" type="number" min="0" max="10000000" step="0.01" value="0" required></label>').join('')+'<label>Activité depuis le<input type="date" name="from" required></label><label>Activité jusqu’au<input type="date" name="to" required></label><button type="button" id="payroll-calc">Calculer les activités</button><p id="payroll-preview">Les montants proposés correspondent aux récoltes et livraisons enregistrées sur la période. Vérifiez les paiements antérieurs avant validation.</p><button>Enregistrer la paie</button></form></div>':'';el.innerHTML='<div class="stats"><div class="stat">💵 Entrées encaissées<strong>'+cash(income)+'</strong></div><div class="stat">💸 Paies enregistrées<strong>'+cash(expenses)+'</strong></div><div class="stat">🏦 Solde estimé<strong>'+cash(income-expenses)+'</strong></div></div><div class="panel"><h2>💰 Historique des paies</h2>'+(admin()?'<button type="button" id="payroll-csv">Exporter les paies (CSV)</button>':'')+tbl(['Date','Employé','Grade','Période couverte','Récoltes','Livraisons','Commandes','Prime direction','Avance','Prime exceptionnelle','Ancienneté','Total','Payé par'],p.slice().reverse().map(x=>[x.payroll_date,x.employee,x.grade||'—',x.data?.period_from&&x.data?.period_to?x.data.period_from+' → '+x.data.period_to:'Archive · période inconnue',cash(x.harvest_amount),cash(x.delivery_amount),cash(x.order_amount),cash(x.management_bonus),cash(x.weekly_advance),cash(x.exceptional_bonus),cash(x.senior_bonus),cash(x.total_amount),x.paid_by||'—']))+'</div>'+payrollForm;if(admin()){document.querySelector('#payroll-csv').onclick=()=>downloadPayrollCsv(p);const form=document.querySelector('#payroll-new');const isoDay=x=>String(x||'').slice(0,10);const localDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const today=localDate(new Date());form.elements.to.value=today;form.elements.to.max=today;form.elements.from.max=today;const monday=new Date();monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-((monday.getDay()+6)%7));form.elements.from.value=localDate(monday);for(const field of ['employee','from','to'])form.elements[field].addEventListener('change',()=>{form.elements.harvest.value='0';form.elements.delivery.value='0';document.querySelector('#payroll-preview').textContent='Période ou employé modifié : cliquez sur « Calculer les activités » pour recalculer les montants.'});document.querySelector('#payroll-calc').onclick=()=>{const f=new FormData(form),name=String(f.get('employee')||'').trim().toLocaleLowerCase('fr'),from=String(f.get('from')),to=String(f.get('to'));if(!name||!from||!to||from>to||to>today)return message('Sélectionnez un employé et une période valide, sans date future.',true);const matching=(x)=>String(x||'').trim().toLocaleLowerCase('fr')===name;const alreadyPaid=payroll.find(x=>matching(x.employee)&&x.data?.period_from&&x.data?.period_to&&x.data.period_from<=to&&x.data.period_to>=from);if(alreadyPaid){form.elements.harvest.value='0';form.elements.delivery.value='0';document.querySelector('#payroll-preview').textContent='⚠️ Période déjà couverte par une paie ('+alreadyPaid.data.period_from+' → '+alreadyPaid.data.period_to+'). Aucun montant proposé : choisissez une période non payée.';return message('Cette période chevauche une paie existante.',true)}const harvest=h.filter(x=>matching(x.employee)&&isoDay(x.harvest_date||x.created_at)>=from&&isoDay(x.harvest_date||x.created_at)<=to);const delivery=deliveries.filter(x=>matching(x.farmer_driver)&&isoDay(x.delivery_date||x.created_at)>=from&&isoDay(x.delivery_date||x.created_at)<=to);const total=xs=>xs.reduce((sum,x)=>sum+Number(x.bonus_amount||0),0);form.elements.harvest.value=total(harvest).toFixed(2);form.elements.delivery.value=total(delivery).toFixed(2);document.querySelector('#payroll-preview').textContent=harvest.length+' récolte(s), '+delivery.length+' livraison(s) sur la période. Récoltes : '+cash(total(harvest))+' ; livraisons : '+cash(total(delivery))+'. Les périodes déjà payées via ce panel sont bloquées à l’enregistrement ; les archives anciennes restent à vérifier. Les montants sont indicatifs et doivent être contrôlés.'};form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),name=String(f.get('employee')||''),employee=employees.find(x=>x.name===name);if(!employee)return message('Employé introuvable.',true);const fromCheck=String(f.get('from')||''),toCheck=String(f.get('to')||'');const overlap=p.find(x=>String(x.employee||'').trim().toLocaleLowerCase('fr')===name.trim().toLocaleLowerCase('fr')&&x.data?.period_from&&x.data?.period_to&&x.data.period_from<=toCheck&&x.data.period_to>=fromCheck);if(overlap)return message('Paie déjà enregistrée sur une période qui se chevauche ('+overlap.data.period_from+' → '+overlap.data.period_to+').',true);const values={};for(const field of ['harvest','delivery','order','management','advance','exceptional','senior']){const value=Number(f.get(field));if(!Number.isFinite(value)||value<0||value>10000000)return message('Montant invalide.',true);values['p_'+field]=value}const gross=values.p_harvest+values.p_delivery+values.p_order+values.p_management+values.p_exceptional+values.p_senior;if(values.p_advance>gross)return message('L’avance ne peut pas dépasser le montant brut de la paie.',true);const from=String(f.get('from')||''),to=String(f.get('to')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to||to>localDate(new Date()))return message('Période invalide : les dates futures sont interdites.',true);const submit=form.querySelector('button[type=submit],button:not([type])');if(submit?.disabled)return;const activeUserId=session?.user?.id;if(!activeUserId)return message('Session expirée : reconnectez-vous.',true);if(submit){submit.disabled=true;submit.textContent='Enregistrement…'}try{const result=await db.rpc('ranch_record_payroll_period',{p_employee:name,p_grade:employee.grade||'',p_from:from,p_to:to,...values});if(result.error)throw result.error;if(session?.user?.id!==activeUserId)return;await load();if(session?.user?.id!==activeUserId)return;draw();message('Paie enregistrée pour '+name+'.')}catch(error){if(session?.user?.id===activeUserId)message('Paie non confirmée : '+(error?.message||'Erreur réseau')+'. Vérifiez l’historique avant toute nouvelle tentative.',true)}finally{if(submit?.isConnected){submit.disabled=false;submit.textContent='Enregistrer la paie'}}}}}
if(tab==='article'&&admin()){el.innerHTML='<div class="panel"><h2>🥕 Articles et conversion des lots</h2><p>1 article Discord correspond au nombre d’unités indiqué ci-dessous. Exemple : 2 × Fromage avec conversion 100 = 200 unités réelles. Pour plateaux, livraison et Click & Collect, indiquez 1.</p>'+tbl(['Article','Catégorie','Prix','Prime %','Unités par article Discord','Actif'],articles.map(x=>[x.name,x.category,cash(x.unit_price),x.data?.primePct??0,x.data?.unitsPerOrder??1,x.active?'Oui':'Non']))+'<h3>Modifier une conversion</h3><form id="conversion"><label>Article<select name="id" required>'+articles.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+' (actuel : '+esc(a.data?.unitsPerOrder??1)+')</option>').join('')+'</select></label><label>Unités réelles pour 1 dans Discord<input type="number" name="units" min="1" step="1" value="100" required></label><button>Enregistrer la conversion</button></form><h3>Ajouter un article</h3><form id="newarticle"><label>Nom<input name="name" required></label><label>Catégorie<input name="category"></label><label>Prix unitaire<input type="number" name="price" min="0" step=".01" required></label><label>Prime (%)<input type="number" name="pct" min="0" max="100" step=".01" required></label><label>Unités réelles pour 1 dans Discord<input type="number" name="units" min="1" step="1" value="1" required></label><button>Ajouter</button></form></div>';document.querySelector('#conversion').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),a=articles.find(x=>String(x.id)===String(f.get('id'))),units=Number(f.get('units'));if(!a||!Number.isSafeInteger(units)||units<1)return message('Conversion invalide.',true);const result=await db.from('ranch_articles').update({data:{...(a.data||{}),unitsPerOrder:units}}).eq('id',a.id);if(result.error)message(result.error.message,true);else{await load();draw();message('Conversion enregistrée : 1 sur Discord = '+units+' unités.')}};document.querySelector('#newarticle').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),units=Number(f.get('units'));if(!Number.isSafeInteger(units)||units<1)return message('Conversion invalide.',true);const result=await db.from('ranch_articles').insert({name:f.get('name'),category:f.get('category'),unit_price:Number(f.get('price')),active:true,data:{primePct:Number(f.get('pct')),unitsPerOrder:units}});if(result.error)message(result.error.message,true);else{await load();draw();message('Article ajouté !')}}}
if(tab==='article'&&admin()){const articlePanel=document.querySelector('#content .panel');if(articlePanel){articlePanel.insertAdjacentHTML('beforeend','<h3>Modifier les informations complètes d’un article</h3><form id="article-full"><label>Article<select name="id">'+articles.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+'</option>').join('')+'</select></label><label>Nom<input name="name" required></label><label>Catégorie<input name="category" required></label><label>Prix de vente ($)<input name="price" type="number" min="0" step=".01" required></label><label>Image (URL HTTPS)<input name="image" type="url"></label><label>Prime récolte (%)<input name="pct" type="number" step=".01" min="0" required></label><label>Stock maximal<input name="max" type="number" min="0" step="1"></label><label>Recette de transformation<textarea name="recipe" rows="3" placeholder="Exemple : Céréales:2"></textarea></label><label>Note de récolte<textarea name="note" rows="3"></textarea></label><label>Visible au catalogue<select name="catalog"><option value="true">Oui</option><option value="false">Non</option></select></label><label>Suivi du stock<select name="tracking"><option value="true">Oui</option><option value="false">Non</option></select></label><label>Grades autorisés à récolter (séparés par |)<input name="grades" placeholder="Patron|Co-patron|Contremaître|Fermier"></label><label>Disponible à la récolte<select name="harvest"><option value="true">Oui</option><option value="false">Non</option></select></label><label>Actif<select name="active"><option value="true">Oui</option><option value="false">Non</option></select></label><button>Enregistrer les modifications</button></form>');const form=document.querySelector('#article-full'),select=form.elements.id;const populate=()=>{const a=articles.find(x=>String(x.id)===String(select.value));if(!a)return;form.elements.name.value=a.name||'';form.elements.category.value=a.category||'';form.elements.price.value=a.unit_price||0;form.elements.image.value=a.data?.image_url||'';form.elements.pct.value=a.data?.primePct??0;form.elements.max.value=a.data?.stockMax??0;form.elements.recipe.value=a.data?.recipe||'';form.elements.note.value=a.data?.harvestNote||'';form.elements.catalog.value=String(a.data?.showInCatalog!==false);form.elements.tracking.value=String(a.data?.stockTracking===true);form.elements.grades.value=Array.isArray(a.data?.harvestGrades)?a.data.harvestGrades.join('|'):String(a.data?.harvestGrades||'');form.elements.harvest.value=String(a.data?.showInHarvest!==false);form.elements.active.value=String(a.active!==false)};select.onchange=populate;populate();form.onsubmit=async e=>{e.preventDefault();const a=articles.find(x=>String(x.id)===String(select.value));if(!a)return;const f=new FormData(form),image=String(f.get('image')).trim();if(image&&!/^https:\/\//i.test(image))return message('Image : URL HTTPS requise.',true);const payload={name:String(f.get('name')).trim(),category:String(f.get('category')).trim(),unit_price:Number(f.get('price')),active:f.get('active')==='true',data:{...a.data,image_url:image,primePct:Number(f.get('pct')),stockMax:Number(f.get('max')),recipe:String(f.get('recipe')),harvestNote:String(f.get('note')),showInCatalog:f.get('catalog')==='true',stockTracking:f.get('tracking')==='true',harvestGrades:String(f.get('grades')).split('|').map(x=>x.trim()).filter(Boolean),showInHarvest:f.get('harvest')==='true'}};const result=await db.from('ranch_articles').update(payload).eq('id',a.id);if(result.error)return message(result.error.message,true);await load();draw();message('Fiche article modifiée.')}}}
